hooks.commandWindows:
& {
    param([string]$root = $env:CLAUDE_PLUGIN_ROOT, [string]$format = 'text')
    try {
        $ErrorActionPreference = 'Stop'
        $legionHome = if ($env:LEGION_HOME) { $env:LEGION_HOME } else { $env:USERPROFILE }
        if (!$root -or !$legionHome) { throw 'Legion root missing' }
        $legionHome = [IO.Path]::GetFullPath($legionHome)
        # The publisher's version is on its own line. Read just that field before Python starts.
        $versions = [regex]::Matches([IO.File]::ReadAllText("$root/plugin.json"), '(?m)^\s*"version"\s*:\s*"([0-9]+(\.[0-9]+){0,2}(-[0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*)?(\+[0-9A-Za-z-]+(\.[0-9A-Za-z-]+)*)?)"')
        if ($versions.Count -ne 1) { throw 'Invalid Legion version' }
        $version = $versions[0].Groups[1].Value

        function Assert-LegionLocalPath([string]$path) {
            if ([IO.File]::GetAttributes($path) -band [IO.FileAttributes]::ReparsePoint) { throw 'Linked Legion path' }
        }

        # Windows PowerShell 5.1 has no ResolveLinkTarget API. Resolve links above the installation,
        # as the 0.17.0 publisher did. Paths below the selected home are checked separately.
        function Get-LegionPhysicalDirectory([IO.DirectoryInfo]$directory, [int]$linksLeft = 40) {
            if (!$directory.Parent) { return $directory.FullName }
            $parent = Get-LegionPhysicalDirectory $directory.Parent $linksLeft
            $item = Get-Item -Force -LiteralPath (Join-Path $parent $directory.Name)
            if ($item.Attributes -band [IO.FileAttributes]::ReparsePoint) {
                $target = $item.Target | Select-Object -First 1
                if (!$target -or $linksLeft -le 0) { throw 'Cannot resolve Legion home' }
                if (![IO.Path]::IsPathRooted($target)) { $target = Join-Path $parent $target }
                return Get-LegionPhysicalDirectory ([IO.DirectoryInfo]$target) ($linksLeft - 1)
            }
            $item.FullName
        }

        $legion = "$legionHome/.legion"
        $app = "$legion/app/$version"
        foreach ($path in @($legion, "$legion/app", $app, "$legion/python")) {
            Assert-LegionLocalPath $path
        }
        $marker = [IO.FileInfo]"$app/.legion-app-ready"
        Assert-LegionLocalPath $marker.FullName
        if ($marker.Length -eq 0) {
            $physical = Get-LegionPhysicalDirectory ([IO.DirectoryInfo]$legionHome)
            $key = [IO.Path]::Combine($physical, '.legion', 'app', $version).ToLowerInvariant()
            $sha = [Security.Cryptography.SHA256]::Create()
            try {
                $digest = [BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($key))).Replace('-', '').ToLowerInvariant()
            } finally {
                $sha.Dispose()
            }
            $name = 'env-' + $digest.Substring(0, 12)
        } else {
            $name = [IO.File]::ReadAllText($marker.FullName)
        }
        if ($name -cnotmatch '\Aenv-[0-9a-f]{12}(\r?\n)?\z') { throw 'Invalid Legion environment' }
        $environment = "$legion/python/$($name.TrimEnd())"
        $python = "$environment/Scripts/python.exe"
        foreach ($path in @($environment, "$environment/Scripts", $python)) {
            Assert-LegionLocalPath $path
        }
        & $python -I -B -S "$root/hooks/session_start.py" --home $legionHome --format $format
        if ($LASTEXITCODE -ne 0) { throw 'Legion hook failed' }
        return
    } catch { }
    if ($format -eq 'context-json') {
        '{"additionalContext":"legion: uv or Python 3.12 is missing, so mode detection did not run; run the legion installer. If LEGION_ROLE=member is set, load the legion-member skill."}'
    } else {
        'legion: uv or Python 3.12 is missing, so mode detection did not run; run the legion installer. If LEGION_ROLE=member is set, load the legion-member skill.'
    }
} @args 2>$null
